def evaluate_records(self, df_validated):
    alerts = []
    for _, row in df_validated.iterrows():
        sid, val, st = row['sensor_id'], row['measurement_value'], row['validation_status']
        if st == 'INVALID_BOUNDS':
            alerts.append({'severity': 'CRITICAL', 'rule': 'RULE-02-PHYSICAL',
                           'desc': f'Nilai {val} di luar batas operasional {sid}'})
        elif st == 'VALID' and sid in self.stats:
            stat = self.stats[sid]
            if val > stat['upper_fence'] or val < stat['lower_fence']:
                alerts.append({'severity': 'MEDIUM', 'rule': 'RULE-03-SPIKE',
                               'desc': f'Lonjakan outlier {val} terdeteksi'}) # Pagar Tukey
    return alerts
